-- V1.8.4 — Saisons privées de club (docs/V184_SAISONS_CLUB.md). Applies after 20261126090000 (V1.8.3).
-- A club runs a private season of 2 to 8 weeks: a title, a start date, a team goal and three stages that unlock with the group's active
-- days, then a private report of its milestones. Everything is built from bricks that already hold:
--   * The club and its roles (20261030090000): only a club ADMINISTRATOR organises (create, postpone the start, stop), with the
--     permission check of titan_club_goal_set_v1 (CLUB_ADMIN_REQUIRED). An organiser does not take part unless they join, like anyone.
--   * EXPLICIT PARTICIPATION: belonging to the club is not consent. Each member chooses to join the season (titan_club_season_act_v1
--     'join'); nobody is ever added. Participation is revocable: pause and resume, or leave for good (acquired days stay with the group).
--     Leaving the club, or being removed from it, ends the participation the same way (trigger on private.titan_club_members).
--   * The measure is the ACTIVE DAY of the Cordée longueur rule (20261120110000): a Paris day with at least 12 counted effort-minutes from
--     CONFIRMED sessions only (private.titan_confirmed_sessions: valid, not suspicious, stamped by the server, no held or cancelled reward),
--     90 minutes a day at most, recorded after the participation started. A day of swimming is worth a day of climbing: every discipline is
--     equal. Days during a pause, before joining or after leaving never count.
--   * The team goal: each participant brings a SHARE = active days per week of the chosen pace (douce 2, régulière 3, soutenue 4) × the
--     weeks they are planned to take part (prorated from their arrival; a pause or a departure frees the rest of their share). The goal is
--     the sum of the shares. A participant counts up to their CAP = 1.5 × the share planned at their arrival, frozen then: a very trained
--     athlete cannot carry the group, and a member who rests does not doom the others.
--   * Three stages at one third, two thirds and the whole goal. A stage unlocks only when the counted total reaches it AND at least two
--     participants have contributed (as soon as the season ever had two): no single account fills the collective part. A stage reached is
--     frozen with its date (row lock): an arrival that raises the goal never re-locks it, a departure never removes acquired days.
--   * CONFIDENTIALITY: the threshold of the club week (20261120100000) — from 3 participants still in the season. Below it, nobody reads a
--     total, a goal, a count of pauses or contributors, or a stage: only the number of participants and one's own days. Never a name, a
--     share or a session of another member; no ranking.
--   * Same inputs, same result: the state is computed by one stable function; the report is frozen once when the season ends or is
--     stopped (status 'closed' or 'stopped') and is never recomputed.
--   * The organiser may postpone a season that has not started (7 or 14 days, twice at most) or stop it (controlled stop: before the
--     start it is cancelled; after, it ends now and its report is frozen with the stages reached).
--   * No XP, credit, title, ranking or reward. Server flag screens.club_season (absent = closed) for create, join, resume and postpone;
--     pausing, leaving and stopping always work. Exported (« clubSeasons ») and erased with the account; a season keeps its report
--     without its organiser (created_by on delete set null). Measure for the pilot: private.titan_club_season_measure (counts only).
-- Additive. The caller owns the transaction: never BEGIN/COMMIT here.
-- Rollback: drop trigger titan_club_members_season on private.titan_club_members; drop functions public.titan_club_season_v1(uuid),
-- public.titan_club_season_act_v1(uuid,text,text,text,integer,date,integer), private.titan_club_season_measure(timestamptz),
-- private.titan_club_season_member_left(), private.titan_club_season_settle(uuid,text), private.titan_club_season_touch(uuid),
-- private.titan_club_season_view(uuid,uuid,text), private.titan_club_season_report(uuid,uuid), private.titan_club_season_state(uuid,uuid),
-- private.titan_club_season_share(uuid,uuid), private.titan_club_season_days(uuid,uuid,timestamptz,timestamptz),
-- private.titan_club_season_ranges(uuid,uuid,timestamptz), private.titan_club_season_per_week(text); re-apply private.titan_social_export_v1
-- from 20261126090000; drop tables private.titan_club_season_pauses, private.titan_club_season_members, private.titan_club_seasons.

-- ---------------------------------------------------------------------------------------------
-- 1. Tables.
-- ---------------------------------------------------------------------------------------------
create table if not exists private.titan_club_seasons (
  id uuid primary key default gen_random_uuid(),
  club_id uuid not null references private.titan_clubs(id) on delete cascade,
  title text not null check (char_length(title) between 3 and 60),
  pace text not null check (pace in ('douce', 'reguliere', 'soutenue')),
  weeks integer not null check (weeks between 2 and 8),
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  postponed integer not null default 0 check (postponed between 0 and 2),
  status text not null default 'open' check (status in ('open', 'closed', 'stopped')),
  stages jsonb not null default '[]'::jsonb check (jsonb_typeof(stages) = 'array' and jsonb_array_length(stages) <= 3),
  summary jsonb,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  stopped_at timestamptz,
  closed_at timestamptz,
  check (ends_at > starts_at)
);
-- One season at a time per club (scheduled or running).
create unique index if not exists titan_club_seasons_open_uniq on private.titan_club_seasons (club_id) where status = 'open';
create index if not exists titan_club_seasons_club_idx on private.titan_club_seasons (club_id, created_at desc);

create table if not exists private.titan_club_season_members (
  season_id uuid not null references private.titan_club_seasons(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  joined_at timestamptz not null default now(),
  left_at timestamptz,
  cap integer not null check (cap >= 1),
  final_days integer,
  primary key (season_id, user_id)
);
create index if not exists titan_club_season_members_user_idx on private.titan_club_season_members (user_id);

create table if not exists private.titan_club_season_pauses (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null,
  user_id uuid not null references auth.users(id) on delete cascade,
  paused_at timestamptz not null default now(),
  resumed_at timestamptz,
  foreign key (season_id, user_id) references private.titan_club_season_members(season_id, user_id) on delete cascade,
  check (resumed_at is null or resumed_at >= paused_at)
);
create unique index if not exists titan_club_season_pauses_open_uniq on private.titan_club_season_pauses (season_id, user_id) where resumed_at is null;

alter table private.titan_club_seasons enable row level security;
alter table private.titan_club_season_members enable row level security;
alter table private.titan_club_season_pauses enable row level security;
revoke all on private.titan_club_seasons, private.titan_club_season_members, private.titan_club_season_pauses from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 2. The measure: active days, shares and caps.
-- ---------------------------------------------------------------------------------------------
create or replace function private.titan_club_season_per_week(p_pace text)
returns integer
language sql
immutable
set search_path = ''
as $$ select case p_pace when 'douce' then 2 when 'soutenue' then 4 else 3 end $$;
revoke all on function private.titan_club_season_per_week(text) from public, anon, authenticated;

-- The time ranges in which a participant takes part: from their arrival (or the start) to their departure (or the end, or the stop),
-- without their pauses, and never beyond p_until. An open pause runs to the end.
create or replace function private.titan_club_season_ranges(p_season uuid, p_user uuid, p_until timestamptz)
returns tstzrange[]
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  s private.titan_club_seasons%rowtype;
  m private.titan_club_season_members%rowtype;
  v_from timestamptz; v_end timestamptz; v_cursor timestamptz;
  v_out tstzrange[] := '{}';
  r record;
begin
  select * into s from private.titan_club_seasons where id = p_season;
  select * into m from private.titan_club_season_members where season_id = p_season and user_id = p_user;
  if s.id is null or m.user_id is null then return v_out; end if;
  v_from := greatest(s.starts_at, m.joined_at);
  v_end := least(s.ends_at, coalesce(s.stopped_at, 'infinity'::timestamptz), coalesce(m.left_at, 'infinity'::timestamptz), p_until);
  if v_from >= v_end then return v_out; end if;
  v_cursor := v_from;
  for r in select p.paused_at, coalesce(p.resumed_at, 'infinity'::timestamptz) as resumed_at
             from private.titan_club_season_pauses p where p.season_id = p_season and p.user_id = p_user order by p.paused_at, p.id loop
    if r.paused_at > v_cursor then v_out := v_out || tstzrange(v_cursor, least(r.paused_at, v_end), '[)'); end if;
    v_cursor := greatest(v_cursor, r.resumed_at);
    exit when v_cursor >= v_end;
  end loop;
  if v_cursor < v_end then v_out := v_out || tstzrange(v_cursor, v_end, '[)'); end if;
  return array(select x from unnest(v_out) as u(x) where not isempty(x));
end;
$function$;
revoke all on function private.titan_club_season_ranges(uuid, uuid, timestamptz) from public, anon, authenticated;

-- Active days of a participant (12 counted minutes from confirmed sessions recorded within the range, 90 a day at most), optionally
-- clipped to [p_from, p_to) (the measure reads the last week).
create or replace function private.titan_club_season_days(p_season uuid, p_user uuid, p_from timestamptz default '-infinity', p_to timestamptz default 'infinity')
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)::integer from (
    select x.day
      from unnest(private.titan_club_season_ranges(p_season, p_user, now())) as u(rng)
      cross join lateral (select u.rng * tstzrange(p_from, p_to, '[)') as clip) c
      cross join lateral private.titan_confirmed_sessions(p_user, lower(c.clip), upper(c.clip), lower(c.clip)) x
     where not isempty(c.clip)
     group by x.day
    having least(90, sum(x.effort_minutes)) >= 12) d;
$$;
revoke all on function private.titan_club_season_days(uuid, uuid, timestamptz, timestamptz) from public, anon, authenticated;

-- A participant's share of the goal: active days per week × planned weeks of participation (ceiled, prorated to the second).
create or replace function private.titan_club_season_share(p_season uuid, p_user uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(ceil(round(private.titan_club_season_per_week(s.pace)
           * coalesce((select sum(extract(epoch from upper(u.rng) - lower(u.rng))) from unnest(private.titan_club_season_ranges(p_season, p_user, 'infinity')) as u(rng)), 0)
           / 604800.0, 6))::integer, 0)
    from private.titan_club_seasons s where s.id = p_season;
$$;
revoke all on function private.titan_club_season_share(uuid, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 3. The state of a season. p_viewer null = the full internal state (touch, settle, measure); otherwise the confidentiality rule applies.
-- ---------------------------------------------------------------------------------------------
create or replace function private.titan_club_season_state(p_season uuid, p_viewer uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  s private.titan_club_seasons%rowtype;
  v_target integer := 0; v_total integer := 0; v_contrib integer := 0; v_in integer := 0; v_paused integer := 0; v_ever integer := 0;
  v_me jsonb; r record; v_days integer; v_share integer; v_counted integer;
  v_stages jsonb := '[]'::jsonb; k integer; v_th integer; v_reached jsonb; v_need integer; v_next integer;
  v_visible boolean; v_phase text; v_week integer;
begin
  select * into s from private.titan_club_seasons where id = p_season;
  if s.id is null then return null; end if;
  for r in select m.*, exists (select 1 from private.titan_club_season_pauses p where p.season_id = m.season_id and p.user_id = m.user_id and p.resumed_at is null) as paused
             from private.titan_club_season_members m where m.season_id = p_season order by m.joined_at, m.user_id loop
    v_ever := v_ever + 1;
    v_days := private.titan_club_season_days(p_season, r.user_id);
    v_share := private.titan_club_season_share(p_season, r.user_id);
    v_counted := least(v_days, r.cap);
    v_target := v_target + v_share;
    v_total := v_total + v_counted;
    if v_counted > 0 then v_contrib := v_contrib + 1; end if;
    if r.left_at is null then v_in := v_in + 1; if r.paused then v_paused := v_paused + 1; end if; end if;
    if p_viewer is not null and r.user_id = p_viewer then
      v_me := jsonb_build_object('status', case when r.left_at is not null then 'left' when r.paused then 'paused' else 'active' end,
        'days', v_counted, 'cap', r.cap, 'share', v_share, 'capped', v_days > r.cap, 'joinedAt', r.joined_at, 'leftAt', r.left_at);
    end if;
  end loop;
  v_need := least(2, v_ever);
  for k in 1..3 loop
    v_th := ceil(v_target * k / 3.0)::integer;
    v_reached := s.stages -> (k - 1);
    v_stages := v_stages || jsonb_build_array(jsonb_build_object('n', k, 'threshold', v_th, 'reachedAt', v_reached,
      'due', v_reached is null and v_target > 0 and v_total >= v_th and v_contrib >= v_need));
    if v_next is null and v_reached is null then v_next := k; end if;
  end loop;
  v_phase := case when s.status = 'stopped' then 'stopped' when s.status = 'closed' or now() >= s.ends_at then 'ended'
                  when now() < s.starts_at then 'upcoming' else 'running' end;
  v_week := case when v_phase = 'running' then least(s.weeks, floor(extract(epoch from now() - s.starts_at) / 604800)::integer + 1) end;
  v_visible := v_in >= 3;
  if p_viewer is not null and not v_visible then
    v_stages := (select jsonb_agg(jsonb_build_object('n', x->'n')) from jsonb_array_elements(v_stages) x);
  elsif p_viewer is not null then
    v_stages := (select jsonb_agg(x - 'due') from jsonb_array_elements(v_stages) x);
  end if;
  return jsonb_build_object('id', s.id, 'club', s.club_id, 'title', s.title, 'pace', s.pace, 'perWeek', private.titan_club_season_per_week(s.pace),
    'weeks', s.weeks, 'startsAt', s.starts_at, 'endsAt', s.ends_at, 'stoppedAt', s.stopped_at, 'postponed', s.postponed, 'phase', v_phase, 'week', v_week,
    'participants', v_in, 'threshold', 3, 'visible', v_visible,
    'ever', case when p_viewer is null then v_ever end,
    'paused', case when p_viewer is null or v_visible then v_paused end,
    'contributors', case when p_viewer is null or v_visible then v_contrib end,
    'total', case when p_viewer is null or v_visible then v_total end,
    'target', case when p_viewer is null or v_visible then v_target end,
    'next', case when p_viewer is null or v_visible then v_next end,
    'stages', v_stages, 'me', v_me);
end;
$function$;
revoke all on function private.titan_club_season_state(uuid, uuid) from public, anon, authenticated;

-- Freezes the report once (the row is locked by the caller): final days of every participant, stages, totals as they stand.
create or replace function private.titan_club_season_settle(p_season uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = ''
as $function$
declare v jsonb; s private.titan_club_seasons%rowtype;
begin
  select * into s from private.titan_club_seasons where id = p_season;
  update private.titan_club_season_members m set final_days = least(private.titan_club_season_days(p_season, m.user_id), m.cap) where m.season_id = p_season;
  v := private.titan_club_season_state(p_season, null);
  update private.titan_club_seasons set status = p_status,
         closed_at = case when p_status = 'closed' then s.ends_at else closed_at end,
         summary = jsonb_build_object('phase', case when p_status = 'stopped' and s.stopped_at <= s.starts_at then 'cancelled' else p_status end,
           'weeks', s.weeks, 'pace', s.pace, 'title', s.title, 'startsAt', s.starts_at, 'endsAt', s.ends_at, 'stoppedAt', s.stopped_at,
           'participants', v->'participants', 'ever', v->'ever', 'visible', v->'visible', 'paused', v->'paused', 'contributors', v->'contributors',
           'total', v->'total', 'target', v->'target',
           'stages', (select jsonb_agg(jsonb_build_object('n', x->'n', 'threshold', x->'threshold', 'reachedAt', x->'reachedAt')) from jsonb_array_elements(v->'stages') x))
   where id = p_season;
end;
$function$;
revoke all on function private.titan_club_season_settle(uuid, text) from public, anon, authenticated;

-- Under the row lock: freeze the stages that are due, settle a season whose end has come. Idempotent.
create or replace function private.titan_club_season_touch(p_season uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $function$
declare s private.titan_club_seasons%rowtype; v jsonb; k integer; v_stages jsonb;
begin
  select * into s from private.titan_club_seasons where id = p_season for update;
  if s.id is null or s.status <> 'open' or now() < s.starts_at then return; end if;
  v := private.titan_club_season_state(p_season, null);
  v_stages := s.stages;
  for k in 0..2 loop
    if coalesce((v->'stages'->k->>'due')::boolean, false) and jsonb_array_length(v_stages) = k then
      v_stages := v_stages || jsonb_build_array(to_jsonb(least(now(), s.ends_at)));
    end if;
  end loop;
  if v_stages is distinct from s.stages then update private.titan_club_seasons set stages = v_stages where id = p_season; end if;
  if now() >= s.ends_at then perform private.titan_club_season_settle(p_season, 'closed'); end if;
end;
$function$;
revoke all on function private.titan_club_season_touch(uuid) from public, anon, authenticated;

-- What a member of the club reads of the current season, with the actions open to them.
create or replace function private.titan_club_season_view(p_season uuid, p_viewer uuid, p_role text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare v jsonb; v_status text; v_can jsonb := '[]'::jsonb; v_suspended boolean;
begin
  v := private.titan_club_season_state(p_season, p_viewer);
  if v is null then return null; end if;
  v_status := v->'me'->>'status';
  v_suspended := exists (select 1 from public.profiles p where p.id = p_viewer and coalesce(p.is_suspended, false));
  if v->>'phase' in ('upcoming', 'running') then
    if v_status is null and not v_suspended then v_can := v_can || '["join"]'::jsonb; end if;
    if v_status = 'active' then v_can := v_can || '["pause", "leave"]'::jsonb; end if;
    if v_status = 'paused' then v_can := v_can || (case when v_suspended then '["leave"]' else '["resume", "leave"]' end)::jsonb; end if;
    if p_role = 'admin' then
      if v->>'phase' = 'upcoming' and (v->>'postponed')::integer < 2 then v_can := v_can || '["postpone"]'::jsonb; end if;
      v_can := v_can || '["stop"]'::jsonb;
    end if;
  end if;
  return v || jsonb_build_object('can', v_can, 'suspended', v_suspended);
end;
$function$;
revoke all on function private.titan_club_season_view(uuid, uuid, text) from public, anon, authenticated;

-- The frozen report, as a member reads it: totals and stages only from the threshold, one's own days always.
create or replace function private.titan_club_season_report(p_season uuid, p_viewer uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object('id', s.id, 'title', s.title, 'pace', s.pace, 'weeks', s.weeks, 'startsAt', s.starts_at, 'endsAt', s.ends_at,
           'stoppedAt', s.stopped_at, 'phase', s.summary->'phase', 'participants', s.summary->'participants', 'threshold', 3,
           'visible', coalesce((s.summary->>'visible')::boolean, false),
           'total', case when (s.summary->>'visible')::boolean then s.summary->'total' end,
           'target', case when (s.summary->>'visible')::boolean then s.summary->'target' end,
           'contributors', case when (s.summary->>'visible')::boolean then s.summary->'contributors' end,
           'stages', case when (s.summary->>'visible')::boolean then s.summary->'stages'
                          else (select jsonb_agg(jsonb_build_object('n', x->'n')) from jsonb_array_elements(s.summary->'stages') x) end,
           'reached', case when (s.summary->>'visible')::boolean then (select count(*) from jsonb_array_elements(s.summary->'stages') x where x->>'reachedAt' is not null) end,
           'me', (select jsonb_build_object('days', m.final_days, 'left', m.left_at is not null) from private.titan_club_season_members m
                   where m.season_id = s.id and m.user_id = p_viewer))
    from private.titan_club_seasons s where s.id = p_season and s.status in ('closed', 'stopped');
$$;
revoke all on function private.titan_club_season_report(uuid, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 4. The API: read and act.
-- ---------------------------------------------------------------------------------------------
create or replace function public.titan_club_season_v1(p_club uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
set statement_timeout = '8s'
as $function$
declare v_uid uuid := auth.uid(); v_role text; v_open uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  select m.role into v_role from private.titan_club_members m join private.titan_clubs c on c.id = m.club_id
   where m.club_id = p_club and m.user_id = v_uid and c.archived_at is null;
  if v_role is null then raise exception 'CLUB_NOT_FOUND' using errcode = 'P0002'; end if;
  select id into v_open from private.titan_club_seasons where club_id = p_club and status = 'open';
  if v_open is not null then
    perform private.titan_club_season_touch(v_open);
    select id into v_open from private.titan_club_seasons where club_id = p_club and status = 'open';
  end if;
  return jsonb_build_object('club', p_club, 'role', case when v_role = 'admin' then 'organizer' else 'member' end,
    'current', case when v_open is not null then private.titan_club_season_view(v_open, v_uid, v_role) end,
    'last', (select private.titan_club_season_report(x.id, v_uid) from private.titan_club_seasons x
              where x.club_id = p_club and x.status in ('closed', 'stopped') and coalesce(x.closed_at, x.stopped_at) > now() - interval '60 days'
              order by coalesce(x.closed_at, x.stopped_at) desc limit 1),
    'canCreate', v_role = 'admin' and v_open is null);
end;
$function$;

create or replace function public.titan_club_season_act_v1(p_club uuid, p_action text, p_title text default null, p_pace text default null,
  p_weeks integer default null, p_starts_on date default null, p_days integer default null)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $function$
declare
  v_uid uuid := auth.uid();
  v_role text;
  s private.titan_club_seasons%rowtype;
  m private.titan_club_season_members%rowtype;
  v_title text := private.titan_club_text(p_title, 60);
  v_today date := (now() at time zone 'Europe/Paris')::date;
  v_start timestamptz;
  v_weeks numeric;
  v_open uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  if p_action is null or p_action not in ('create', 'join', 'pause', 'resume', 'leave', 'postpone', 'stop') then raise exception 'SEASON_INVALID' using errcode = '22023'; end if;
  if p_action in ('create', 'join', 'resume', 'postpone') and not private.titan_flag_on('screens.club_season') then raise exception 'FEATURE_DISABLED' using errcode = '42501'; end if;
  select cm.role into v_role from private.titan_club_members cm join private.titan_clubs c on c.id = cm.club_id
   where cm.club_id = p_club and cm.user_id = v_uid and c.archived_at is null;
  if v_role is null then raise exception 'CLUB_NOT_FOUND' using errcode = 'P0002'; end if;
  if p_action in ('create', 'postpone', 'stop') and v_role <> 'admin' then raise exception 'CLUB_ADMIN_REQUIRED' using errcode = '42501'; end if;
  if p_action in ('create', 'join', 'resume') and exists (select 1 from public.profiles p where p.id = v_uid and coalesce(p.is_suspended, false)) then
    raise exception 'ACCOUNT_SUSPENDED' using errcode = '42501';
  end if;
  -- Every action on a club's season goes through the club row lock: two organisers, or a join and a stop, are serialised.
  perform 1 from private.titan_clubs where id = p_club for update;

  if p_action = 'create' then
    if not private.titan_can_vote(v_uid) then raise exception 'NOT_ELIGIBLE' using errcode = '42501'; end if;
    perform private.titan_rate_limit(v_uid, 'club_season', 10);
    if v_title is null or char_length(v_title) < 3 or char_length(v_title) > 60 or p_pace is null or p_pace not in ('douce', 'reguliere', 'soutenue')
       or p_weeks is null or p_weeks not between 2 and 8 or p_starts_on is null or p_starts_on < v_today or p_starts_on > v_today + 28 then
      raise exception 'SEASON_INVALID' using errcode = '22023';
    end if;
    select id into v_open from private.titan_club_seasons where club_id = p_club and status = 'open';
    if v_open is not null then
      perform private.titan_club_season_touch(v_open);
      if exists (select 1 from private.titan_club_seasons where id = v_open and status = 'open') then raise exception 'SEASON_OPEN' using errcode = '22023'; end if;
    end if;
    v_start := p_starts_on::timestamp at time zone 'Europe/Paris';
    insert into private.titan_club_seasons (club_id, title, pace, weeks, starts_at, ends_at, created_by)
    values (p_club, v_title, p_pace, p_weeks, v_start, v_start + make_interval(days => p_weeks * 7), v_uid);
    return public.titan_club_season_v1(p_club);
  end if;

  select * into s from private.titan_club_seasons where club_id = p_club and status = 'open' for update;
  if s.id is null then raise exception 'SEASON_NOT_FOUND' using errcode = 'P0002'; end if;
  perform private.titan_club_season_touch(s.id);
  select * into s from private.titan_club_seasons where id = s.id;
  if s.status <> 'open' then raise exception 'SEASON_ENDED' using errcode = '22023'; end if;
  select * into m from private.titan_club_season_members where season_id = s.id and user_id = v_uid;

  if p_action = 'join' then
    if m.user_id is not null and m.left_at is not null then raise exception 'SEASON_LEFT' using errcode = '22023'; end if;
    if m.user_id is null then
      perform private.titan_rate_limit(v_uid, 'club_season_join', 30);
      -- The cap is frozen at arrival: 1.5 × the share planned from now (or from the start) to the end.
      v_weeks := extract(epoch from s.ends_at - greatest(now(), s.starts_at)) / 604800.0;
      insert into private.titan_club_season_members (season_id, user_id, cap)
      values (s.id, v_uid, greatest(1, ceil(round(1.5 * private.titan_club_season_per_week(s.pace) * v_weeks, 6))::integer));
    end if;
  elsif p_action = 'pause' then
    if m.user_id is null or m.left_at is not null then raise exception 'SEASON_NOT_IN' using errcode = '22023'; end if;
    insert into private.titan_club_season_pauses (season_id, user_id) values (s.id, v_uid) on conflict do nothing;
  elsif p_action = 'resume' then
    if m.user_id is null or m.left_at is not null then raise exception 'SEASON_NOT_IN' using errcode = '22023'; end if;
    update private.titan_club_season_pauses set resumed_at = now() where season_id = s.id and user_id = v_uid and resumed_at is null;
  elsif p_action = 'leave' then
    if m.user_id is null or m.left_at is not null then raise exception 'SEASON_NOT_IN' using errcode = '22023'; end if;
    update private.titan_club_season_pauses set resumed_at = now() where season_id = s.id and user_id = v_uid and resumed_at is null;
    update private.titan_club_season_members set left_at = now() where season_id = s.id and user_id = v_uid;
  elsif p_action = 'postpone' then
    if now() >= s.starts_at then raise exception 'SEASON_STARTED' using errcode = '22023'; end if;
    if s.postponed >= 2 then raise exception 'SEASON_POSTPONE_LIMIT' using errcode = '22023'; end if;
    if p_days is null or p_days not in (7, 14) then raise exception 'SEASON_INVALID' using errcode = '22023'; end if;
    update private.titan_club_seasons set starts_at = starts_at + make_interval(days => p_days), ends_at = ends_at + make_interval(days => p_days),
           postponed = postponed + 1 where id = s.id;
    -- The caps of those who already joined follow the new dates (the share planned is the same whole season).
    update private.titan_club_season_members set cap = greatest(1, ceil(round(1.5 * private.titan_club_season_per_week(s.pace) * s.weeks, 6))::integer)
     where season_id = s.id;
  elsif p_action = 'stop' then
    update private.titan_club_seasons set stopped_at = now() where id = s.id;
    update private.titan_club_season_pauses set resumed_at = now() where season_id = s.id and resumed_at is null;
    perform private.titan_club_season_touch(s.id);
    if exists (select 1 from private.titan_club_seasons where id = s.id and status = 'open') then perform private.titan_club_season_settle(s.id, 'stopped'); end if;
  end if;
  return public.titan_club_season_v1(p_club);
end;
$function$;
revoke all on function public.titan_club_season_v1(uuid), public.titan_club_season_act_v1(uuid, text, text, text, integer, date, integer) from public, anon;
grant execute on function public.titan_club_season_v1(uuid), public.titan_club_season_act_v1(uuid, text, text, text, integer, date, integer) to authenticated;

-- Leaving the club, or being removed from it, ends the participation in its open season; acquired days stay with the group.
create or replace function private.titan_club_season_member_left()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
begin
  -- An erased account takes its participation with it (cascade): nothing to end.
  if not exists (select 1 from auth.users u where u.id = old.user_id) then return old; end if;
  update private.titan_club_season_pauses p set resumed_at = now()
    from private.titan_club_seasons s
   where s.id = p.season_id and s.club_id = old.club_id and s.status = 'open' and p.user_id = old.user_id and p.resumed_at is null;
  update private.titan_club_season_members m set left_at = now()
    from private.titan_club_seasons s
   where s.id = m.season_id and s.club_id = old.club_id and s.status = 'open' and m.user_id = old.user_id and m.left_at is null;
  return old;
end;
$function$;
revoke all on function private.titan_club_season_member_left() from public, anon, authenticated;
drop trigger if exists titan_club_members_season on private.titan_club_members;
create trigger titan_club_members_season after delete on private.titan_club_members
  for each row execute function private.titan_club_season_member_left();

-- ---------------------------------------------------------------------------------------------
-- 5. The account export (cumulative): one's own participations and pauses, the seasons one organised; never another member.
-- ---------------------------------------------------------------------------------------------
create or replace function private.titan_social_export_v1(p_uid uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'friendInvites', coalesce((select jsonb_agg(jsonb_build_object('created_at', i.created_at, 'expires_at', i.expires_at, 'revoked_at', i.revoked_at,
                       'used_at', i.used_at) order by i.created_at) from private.titan_friend_invites i where i.created_by = p_uid), '[]'::jsonb),
    'cordeeTitles', coalesce((select jsonb_agg(jsonb_build_object('route', t.route, 'challenge_id', t.challenge_id, 'earned_at', t.earned_at)
                       order by t.earned_at, t.route) from private.titan_cordee_titles t where t.user_id = p_uid), '[]'::jsonb),
    'cordeeRelays', coalesce((select jsonb_agg(x.j order by x.at) from (
        select r.opened_at as at, jsonb_build_object('challenge_id', r.challenge_id, 'step', r.step, 'action', 'transmit', 'at', r.opened_at,
               'log_id', r.opened_log, 'day', r.opened_day) as j from private.titan_cordee_relays r where r.opened_by = p_uid
        union all
        select r.confirmed_at, jsonb_build_object('challenge_id', r.challenge_id, 'step', r.step, 'action', 'confirm', 'at', r.confirmed_at,
               'log_id', r.confirmed_log, 'day', r.confirmed_day) from private.titan_cordee_relays r where r.confirmed_by = p_uid) x), '[]'::jsonb),
    'cordeeRelayTurns', coalesce((select jsonb_agg(jsonb_build_object('challenge_id', t.challenge_id, 'kind', t.kind,
        'role', case when t.kind = 'take' then 'took' when t.from_user = p_uid then 'offered' when t.accepted_by = p_uid then 'accepted' else 'offered_to_me' end,
        'open', case when t.kind = 'handover' then t.to_user is null end, 'status', t.status, 'at', t.created_at, 'expires_at', t.expires_at,
        'resolved_at', t.resolved_at) order by t.created_at)
      from private.titan_cordee_relay_turns t where t.from_user = p_uid or t.to_user = p_uid or t.accepted_by = p_uid), '[]'::jsonb),
    'cordeeSuites', coalesce((select jsonb_agg(x.j order by x.at) from (
        select s.created_at as at, jsonb_build_object('from_id', s.from_id, 'role', 'proposed', 'route', s.route, 'pace', s.pace, 'days', s.days,
               'status', s.status, 'at', s.created_at, 'started_id', s.started_id) as j
          from private.titan_cordee_suites s where s.proposed_by = p_uid
        union all
        select a.answered_at, jsonb_build_object('from_id', s.from_id, 'role', 'answered', 'answer', a.answer, 'route', s.route, 'pace', s.pace,
               'days', s.days, 'at', a.answered_at)
          from private.titan_cordee_suite_answers a join private.titan_cordee_suites s on s.id = a.suite_id
         where a.user_id = p_uid and s.proposed_by is distinct from p_uid) x), '[]'::jsonb),
    'clubSeasons', coalesce((select jsonb_agg(x.j order by x.at) from (
        select s.created_at as at, jsonb_build_object('season_id', s.id, 'club_id', s.club_id, 'role', 'organised', 'title', s.title, 'pace', s.pace,
               'weeks', s.weeks, 'starts_at', s.starts_at, 'status', s.status, 'at', s.created_at) as j
          from private.titan_club_seasons s where s.created_by = p_uid
        union all
        select m.joined_at, jsonb_build_object('season_id', m.season_id, 'club_id', s.club_id, 'role', 'took_part', 'title', s.title, 'joined_at', m.joined_at,
               'left_at', m.left_at, 'final_days', m.final_days,
               'pauses', coalesce((select jsonb_agg(jsonb_build_object('paused_at', p.paused_at, 'resumed_at', p.resumed_at) order by p.paused_at)
                                     from private.titan_club_season_pauses p where p.season_id = m.season_id and p.user_id = p_uid), '[]'::jsonb))
          from private.titan_club_season_members m join private.titan_club_seasons s on s.id = m.season_id where m.user_id = p_uid) x), '[]'::jsonb));
$$;
revoke all on function private.titan_social_export_v1(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 6. The measure of the pilot: seasons started, stages held, groups still active in their last week. Counts only.
-- ---------------------------------------------------------------------------------------------
create or replace function private.titan_club_season_measure(p_since timestamptz default now() - interval '56 days')
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with st as (
    select s.* from private.titan_club_seasons s
     where s.starts_at >= p_since and s.starts_at <= now() and (s.stopped_at is null or s.stopped_at > s.starts_at)),
  fin as (
    select st.id, least(st.ends_at, coalesce(st.stopped_at, 'infinity'::timestamptz), now()) as last_day from st
     where st.status in ('closed', 'stopped') or st.ends_at <= now()),
  lw as (
    select fin.id, (select count(*) from private.titan_club_season_members m
                     where m.season_id = fin.id and private.titan_club_season_days(fin.id, m.user_id, fin.last_day - interval '7 days', fin.last_day) > 0) as active
      from fin)
  select jsonb_build_object('since', p_since,
    'seasonsStarted', (select count(*) from st),
    'withParticipants', (select count(*) from st where (select count(*) from private.titan_club_season_members m where m.season_id = st.id) >= 3),
    'stagesHeld', coalesce((select sum(jsonb_array_length(st.stages)) from st), 0),
    'byStage', jsonb_build_object('1', (select count(*) from st where jsonb_array_length(st.stages) >= 1),
                                  '2', (select count(*) from st where jsonb_array_length(st.stages) >= 2),
                                  '3', (select count(*) from st where jsonb_array_length(st.stages) >= 3)),
    'finished', (select count(*) from fin),
    'activeLastWeek', (select count(*) from lw where lw.active >= 2),
    'stoppedEarly', (select count(*) from st where st.status = 'stopped'),
    'cancelledBeforeStart', (select count(*) from private.titan_club_seasons s where s.created_at >= p_since and s.status = 'stopped' and s.stopped_at <= s.starts_at));
$$;
revoke all on function private.titan_club_season_measure(timestamptz) from public, anon, authenticated;
grant execute on function private.titan_club_season_measure(timestamptz) to service_role;

notify pgrst, 'reload schema';
